import type { MultiSelectTriggerProps } from "../multi-select.types";

import React, { forwardRef, useEffect, useRef } from "react";
import { Menu } from "@components/menu";

import { MultiSelectClasses } from "../multi-select.styles";
import { useMultiSelect } from "../hooks/use-multi-select";

export const MultiSelectTrigger = forwardRef<HTMLDivElement, MultiSelectTriggerProps>(
  ({ children, ...props }, ref) => {
    const {
      setTriggerWidth,
      disabled,
      triggerRef,
      contentId,
      open,
      activeDescendant,
      "aria-invalid": ariaInvalid,
      "aria-describedby": ariaDescribedby,
      "aria-labelledby": ariaLabelledBy,
      "aria-required": ariaRequired,
      id,
    } = useMultiSelect();
    const buttonRef = useRef<HTMLDivElement>(null);

    useEffect(() => {
      const resizeObserver = new ResizeObserver((entries) => {
        for (const entry of entries) {
          setTriggerWidth(entry.target.getBoundingClientRect().width);
        }
      });

      if (buttonRef.current) {
        resizeObserver.observe(buttonRef.current);
      }

      return () => {
        resizeObserver.disconnect();
      };
    }, [setTriggerWidth, buttonRef]);

    return (
      <Menu.Trigger
        {...props}
        ref={(node) => {
          if (typeof ref === "function") {
            ref(node);
          } else if (ref) {
            ref.current = node;
          }
          (triggerRef as React.MutableRefObject<HTMLDivElement | null>).current = node;
        }}
        disabled={disabled}
      >
        <div
          ref={buttonRef}
          aria-activedescendant={activeDescendant}
          aria-controls={contentId}
          aria-describedby={ariaDescribedby}
          aria-disabled={disabled}
          aria-expanded={open}
          aria-haspopup="listbox"
          aria-invalid={ariaInvalid}
          aria-labelledby={ariaLabelledBy}
          aria-required={ariaRequired}
          className={MultiSelectClasses.trigger}
          data-disabled={disabled}
          id={id}
          role="combobox"
          tabIndex={disabled ? -1 : 0}
        >
          <div className={MultiSelectClasses.triggerContent}>{children}</div>
        </div>
      </Menu.Trigger>
    );
  },
);
MultiSelectTrigger.displayName = "MultiSelect.Trigger";
